"""Strict CSV-to-JSON helpers and command-line tool."""

from __future__ import annotations

import csv
import io
import json
import sys
from collections.abc import Iterable, Mapping
from typing import Any

_HEADER = ["name", "note"]
_REQUIRED_KEYS = frozenset(_HEADER)


def _validate_csv_syntax(text: str) -> None:
    """Reject quote placement that the permissive CSV parser may accept."""
    field_start = 0
    unquoted = 1
    quoted = 2
    after_quote = 3
    state = field_start

    for position, character in enumerate(text):
        if state == field_start:
            if character == '"':
                state = quoted
            elif character == ',':
                pass
            elif character in '\r\n':
                pass
            else:
                state = unquoted
        elif state == unquoted:
            if character == '"':
                raise ValueError(
                    f"malformed CSV: unexpected quote at character {position}"
                )
            if character == ',':
                state = field_start
            elif character in '\r\n':
                state = field_start
        elif state == quoted:
            if character == '"':
                state = after_quote
        else:  # after_quote
            if character == '"':
                state = quoted
            elif character == ',':
                state = field_start
            elif character in '\r\n':
                state = field_start
            else:
                raise ValueError(
                    "malformed CSV: expected a comma or line ending after "
                    f"a closing quote at character {position}"
                )

    if state == quoted:
        raise ValueError("malformed CSV: unterminated quoted field")


def parse_records(text: str) -> list[dict[str, str]]:
    """Parse CSV with the exact two-column header ``name,note``."""
    if not isinstance(text, str):
        raise ValueError("CSV input must be a string")

    _validate_csv_syntax(text)
    reader = csv.reader(io.StringIO(text, newline=""), strict=True)

    try:
        header = next(reader, None)
        if header is None:
            raise ValueError("missing CSV header; expected name,note")
        if header != _HEADER:
            raise ValueError("invalid CSV header; expected name,note")

        records: list[dict[str, str]] = []
        for row in reader:
            if len(row) != 2:
                raise ValueError(
                    f"invalid column count on CSV row {reader.line_num}; expected 2"
                )
            records.append({"name": row[0], "note": row[1]})
        return records
    except csv.Error as exc:
        raise ValueError(f"malformed CSV: {exc}") from None


def format_records(records: Iterable[Mapping[str, Any]]) -> str:
    """Serialize validated name/note records using LF line endings."""
    try:
        iterator = iter(records)
    except TypeError:
        raise ValueError("records must be an iterable of mappings") from None

    output = io.StringIO(newline="")
    writer = csv.writer(output, lineterminator="\n")
    writer.writerow(_HEADER)

    try:
        for index, record in enumerate(iterator):
            if not isinstance(record, Mapping):
                raise ValueError(f"record {index} must be a mapping")
            if frozenset(record.keys()) != _REQUIRED_KEYS:
                raise ValueError(
                    f"record {index} must contain exactly the keys name and note"
                )

            name = record["name"]
            note = record["note"]
            if not isinstance(name, str) or not isinstance(note, str):
                raise ValueError(f"record {index} values must be strings")
            writer.writerow((name, note))
    except csv.Error as exc:
        raise ValueError(f"could not format CSV: {exc}") from None

    return output.getvalue()


def to_json(text: str) -> str:
    """Parse CSV and return a Unicode-preserving JSON representation."""
    return json.dumps(parse_records(text), ensure_ascii=False)


def main() -> int:
    """Run the stdin-to-JSON command-line interface."""
    try:
        result = to_json(sys.stdin.read())
    except ValueError as exc:
        print(f"csv_tool.py: {exc}", file=sys.stderr)
        return 2

    sys.stdout.write(result)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
